export default async function handler(req, res) {
  try {
    // Fallback to local if env is not defined, typically available in Vercel.
    const apiUrl = process.env.VITE_API_URL || 'http://localhost:5000/api';
    
    // Determine the frontend URL dynamically
    const protocol = req.headers['x-forwarded-proto'] || 'https';
    const host = req.headers['x-forwarded-host'] || req.headers.host || 'travelbharat.in';
    const frontendUrl = `${protocol}://${host}`;

    // Helper to fetch data safely
    const fetchData = async (endpoint, dataKey) => {
      try {
        const response = await fetch(`${apiUrl}${endpoint}?limit=5000`);
        if (!response.ok) return [];
        const json = await response.json();
        if (json.data && Array.isArray(json.data[dataKey])) {
          return json.data[dataKey];
        }
        return [];
      } catch (error) {
        console.error(`Error fetching ${endpoint}:`, error);
        return [];
      }
    };

    // Fetch lists
    const [states, cities, places, festivals, blogs] = await Promise.all([
      fetchData('/states', 'states'),
      fetchData('/cities', 'cities'),
      fetchData('/places', 'places'),
      fetchData('/festivals', 'festivals'),
      fetchData('/blogs', 'blogs'),
    ]);

    // Start constructing the XML
    let sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <url>
    <loc>${frontendUrl}/</loc>
    <changefreq>daily</changefreq>
    <priority>1.0</priority>
  </url>
  <url>
    <loc>${frontendUrl}/states</loc>
    <changefreq>weekly</changefreq>
    <priority>0.8</priority>
  </url>
  <url>
    <loc>${frontendUrl}/cities</loc>
    <changefreq>weekly</changefreq>
    <priority>0.8</priority>
  </url>
  <url>
    <loc>${frontendUrl}/places</loc>
    <changefreq>weekly</changefreq>
    <priority>0.8</priority>
  </url>
  <url>
    <loc>${frontendUrl}/festivals</loc>
    <changefreq>weekly</changefreq>
    <priority>0.8</priority>
  </url>
  <url>
    <loc>${frontendUrl}/blogs</loc>
    <changefreq>weekly</changefreq>
    <priority>0.8</priority>
  </url>
  <url>
    <loc>${frontendUrl}/plan</loc>
    <changefreq>weekly</changefreq>
    <priority>0.8</priority>
  </url>
  <url>
    <loc>${frontendUrl}/about</loc>
    <changefreq>monthly</changefreq>
    <priority>0.5</priority>
  </url>
  <url>
    <loc>${frontendUrl}/contact</loc>
    <changefreq>monthly</changefreq>
    <priority>0.5</priority>
  </url>
  <url>
    <loc>${frontendUrl}/privacy-policy</loc>
    <changefreq>yearly</changefreq>
    <priority>0.3</priority>
  </url>
  <url>
    <loc>${frontendUrl}/terms-of-service</loc>
    <changefreq>yearly</changefreq>
    <priority>0.3</priority>
  </url>`;

    // Helper to add URLs
    const addUrl = (path, priority = 0.6) => {
      sitemap += `
  <url>
    <loc>${frontendUrl}${path}</loc>
    <priority>${priority}</priority>
  </url>`;
    };

    if (Array.isArray(states)) {
      states.forEach(state => {
        if (state.slug) addUrl(`/states/${state.slug}`, 0.9);
      });
    }

    if (Array.isArray(cities)) {
      cities.forEach(city => {
        if (city.slug) {
          const stateSlug = city.stateId?.slug || city.state?.slug || 'state';
          addUrl(`/states/${stateSlug}/cities/${city.slug}`, 0.8);
        }
      });
    }

    if (Array.isArray(places)) {
      places.forEach(place => {
        if (place.slug) {
          // Backward compatibility route is safer if state/city slugs are nested differently
          addUrl(`/places/${place.slug}`, 0.7);
        }
      });
    }

    if (Array.isArray(festivals)) {
      festivals.forEach(festival => {
        if (festival.slug) addUrl(`/festivals/${festival.slug}`, 0.7);
      });
    }

    if (Array.isArray(blogs)) {
      blogs.forEach(blog => {
        if (blog.slug) addUrl(`/blogs/${blog.slug}`, 0.7);
      });
    }

    sitemap += `\n</urlset>`;

    res.setHeader('Content-Type', 'text/xml');
    res.setHeader('Cache-Control', 's-maxage=86400, stale-while-revalidate');
    res.status(200).send(sitemap);
  } catch (err) {
    console.error('Sitemap generation error:', err);
    res.status(500).send('Error generating sitemap');
  }
}

import js from '@eslint/js'
import globals from 'globals'
import reactHooks from 'eslint-plugin-react-hooks'
import reactRefresh from 'eslint-plugin-react-refresh'
import { defineConfig, globalIgnores } from 'eslint/config'

export default defineConfig([
  globalIgnores(['dist']),
  {
    files: ['**/*.{js,jsx}'],
    extends: [
      js.configs.recommended,
      // reactHooks.configs.recommended,
      // reactRefresh.configs.recommended,
    ],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
      parserOptions: {
        ecmaVersion: 'latest',
        ecmaFeatures: { jsx: true },
        sourceType: 'module',
      },
    },
    rules: {
      'no-unused-vars': ['error', { varsIgnorePattern: '^[A-Z_]' }],
    },
  },
])

const fs = require('fs');
const path = require('path');

const walk = (dir) => {
    let results = [];
    const list = fs.readdirSync(dir);
    list.forEach(file => {
        file = path.join(dir, file);
        const stat = fs.statSync(file);
        if (stat && stat.isDirectory()) {
            results = results.concat(walk(file));
        } else if (file.endsWith('.jsx')) {
            results.push(file);
        }
    });
    return results;
};

const dir = 'g:/Projects/TravelBharat/travelbharat-frontend/src/features/admin';
const files = walk(dir);

let modified = 0;
files.forEach(file => {
    let content = fs.readFileSync(file, 'utf8');
    let orig = content;

    content = content.replace(/src={([^}]+?\.(?:images\.thumbnail|images\.hero|profileImage|coverImage|image))}/g, (match, p1) => {
        if (p1.includes('||')) {
            let newP1 = p1.replace(/([\w\.]+?\.(?:images\.thumbnail|images\.hero|profileImage|coverImage|image))/g, '($1?.url || $1)');
            return `src={${newP1}}`;
        }
        return `src={${p1}?.url || ${p1}}`;
    });

    content = content.replace(/<ImageTile\s+src={([^}]+?\.(?:images\.thumbnail|images\.hero|profileImage|coverImage|image))}/g, (match, p1) => {
        if (p1.includes('||')) {
            let newP1 = p1.replace(/([\w\.]+?\.(?:images\.thumbnail|images\.hero|profileImage|coverImage|image))/g, '($1?.url || $1)');
            return `<ImageTile src={${newP1}}`;
        }
        return `<ImageTile src={${p1}?.url || ${p1}}`;
    });

    if (orig !== content) {
        fs.writeFileSync(file, content, 'utf8');
        modified++;
    }
});

console.log('Modified files:', modified);

import { useEffect, useState } from "react";
import "../App.css";
import "react-toastify/dist/ReactToastify.css";
import { ToastContainer } from "react-toastify";
import ScrollToTop from "../layout/core/ScrollToTop";
import ScrollToTopButton from "../components/ui/ScrollToTopButton";
import AppRoutes from "./routes/AppRoutes";
import { useTheme } from "../hooks/useTheme";

function App() {
  const { theme, toggleTheme } = useTheme();

  return (
    <>
      <ScrollToTop />
      <ScrollToTopButton />
      <ToastContainer autoClose={5000} position="top-right" newestOnTop />
      <AppRoutes theme={theme} toggleTheme={toggleTheme} />
    </>
  );
}

export default App;

import { Link } from "react-router-dom";
import { FiPlus } from "react-icons/fi";

const AdminPageLayout = ({ 
  title, 
  subtitle, 
  actionLabel, 
  actionLink, 
  actionIcon: ActionIcon = FiPlus,
  stats,
  children 
}) => {
  return (
    <div className="p-4 md:p-8 space-y-6 md:space-y-8 max-w-7xl mx-auto w-full">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-slate-900 dark:text-white mb-2">{title}</h1>
          {subtitle && <p className="text-slate-500 dark:text-slate-400 text-sm">{subtitle}</p>}
        </div>
        
        {actionLabel && actionLink && (
          <div className="flex items-center gap-3">
            <Link 
              to={actionLink} 
              className="px-5 py-2.5 bg-[#E85D04] hover:bg-[#c44e03] text-white font-bold rounded-xl flex items-center gap-2 shadow-lg hover:shadow-xl hover:-translate-y-0.5 transition-all"
            >
              <ActionIcon size={18} /> {actionLabel}
            </Link>
          </div>
        )}
      </div>

      {/* Stats Overview */}
      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {stats.map((stat, idx) => {
            const Icon = stat.icon;
            return (
              <div key={idx} className="bg-white dark:bg-[#0A121F] p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex items-center gap-4 hover:shadow-md transition">
                <div className={`p-3 rounded-xl ${stat.colorClass || 'bg-slate-100 dark:bg-slate-800 text-slate-500'}`}>
                  {Icon && <Icon size={24} />}
                </div>
                <div>
                  <p className="text-sm font-bold text-slate-500 dark:text-slate-400">{stat.label}</p>
                  <p className="text-2xl font-black text-slate-900 dark:text-white">{stat.value}</p>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Main Content (Filters, Tables, Grids) */}
      <div className="space-y-6">
        {children}
      </div>
    </div>
  );
};

export default AdminPageLayout;

import { motion } from "framer-motion";
import { fadeUp } from "../../animations/motionVariants";

const CareServiceCard = ({ Icon, Title, Description }) => {
  return (
    <motion.div
      variants={fadeUp}
      initial="hidden"
      whileInView="show"
      viewport={{ once: true, amount: 0.2 }}
      className="group rounded-xl border-t border-white/10 bg-slate-500/10 p-5 backdrop-blur-2xl transition duration-300 hover:scale-105 hover:border-blue-500"
    >
      <div className="inline-flex rounded-xl bg-blue-600 dark:bg-slate-400/30 p-3">
        {Icon && <Icon size={22} className="text-slate-100" />}
      </div>
      <p className="mt-4 font-semibold text-slate-800 dark:text-white">{Title}</p>
      <p className="text-slate-400">{Description}</p>
    </motion.div>
  );
};

export default CareServiceCard;

import { Link } from "react-router-dom";
import { motion } from "framer-motion";
import {
  FiMapPin,
  FiCompass,
  FiCalendar,
  FiStar,
  FiArrowRight,
} from "react-icons/fi";
import { FaMapMarkerAlt } from "react-icons/fa";
import TravelBadge from "../ui/TravelBadge";

const TravelCard = ({ data, type, stateSlug, citySlug, index = 0 }) => {
  const image =
    data.images?.thumbnail?.url ||
    data.images?.hero?.url ||
    data.heroImage?.url;

  const name = data.name || "";

  const description = data.tagline || data.description || data.overview || "";

  let url = "#";

  switch (type) {
    case "state":
      url = `/states/${data.slug}`;
      break;
    case "city":
      url = `/states/${stateSlug}/cities/${data.slug}`;
      break;
    case "place":
      url = `/states/${stateSlug}/cities/${citySlug}/places/${data.slug}`;
      break;
    case "festival":
      url = `/festivals/${data.slug}`;
      break;
    default:
      url = "#";
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 30 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-40px" }}
      transition={{
        duration: 0.55,
        delay: index * 0.05,
        ease: [0.25, 0.46, 0.45, 0.94],
      }}
      className="group h-[380px] sm:h-[430px]"
    >
      <Link
        to={url}
        aria-label={name}
        className=" relative flex flex-col h-full overflow-hidden rounded-[28px] bg-surface border border-border-theme shadow-lg shadow-slate-300/20 dark:shadow-black/40 hover:-translate-y-2 hover:border-orange-500/40 hover:shadow-2xl hover:shadow-orange-500/10 transition-all duration-500 "
      >
        <div className="relative h-[72%] overflow-hidden">
          {image ? (
            <img
              src={image}
              alt={name}
              loading="lazy"
              className="h-full w-full object-cover transition-transform duration-700group-hover:scale-110"
            />
          ) : (
            <div className="flex h-full w-full items-center justify-center bg-surface-elevated">
              <FiMapPin
                size={58}
                className="text-slate-400 dark:text-slate-500"
              />
            </div>
          )}
          <div className=" absolute inset-0 bg-linear-to-t from-black/75 via-black/20 to-black/10 group-hover:from-black/80 group-hover:via-black/15 transition-all duration-500 " />

          <div className=" absolute inset-x-0 top-0 h-28 bg-linear-to-b from-black/40 to-transparent" />

          <div className="absolute left-5 top-5 z-20">
            {data.primaryBadge || data.badge ? (
              <TravelBadge badgeName={data.primaryBadge || data.badge?.name} />
            ) : (
              <div className="flex gap-2">
                {(type === "state" || type === "city") &&
                  data.totalPlaces > 0 && (
                    <span className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-black/45 px-4 py-2 text-[10px] font-bold uppercase tracking-wider text-white backdrop-blur-xl ">
                      <FiCompass className="text-orange-400" size={12} />
                      {data.totalPlaces}{" "}
                      {data.totalPlaces === 1 ? "Place" : "Places"}
                    </span>
                  )}

                {type === "place" && data.category?.name && (
                  <span className="rounded-full border border-white/15 bg-black/45 px-4 py-2 text-[10px] font-bold uppercase tracking-wider text-white backdrop-blur-xl ">
                    {data.category.name}
                  </span>
                )}

                {type === "festival" && data.month && (
                  <span className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-black/45 px-4 py-2 text-[10px] font-bold uppercase tracking-wider text-white backdrop-blur-xl ">
                    <FiCalendar className="text-orange-400" size={12} />
                    {data.month}
                  </span>
                )}

                {type === "festival" && data.month && (
                  <span className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-black/45 px-4 py-2 text-[10px] font-bold uppercase tracking-wider text-white backdrop-blur-xl ">
                    {data.category.name}
                  </span>
                )}

                {type === "festival" && data.month && (
                  <span className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-black/45 px-4 py-2 text-[10px] font-bold uppercase tracking-wider text-white backdrop-blur-xl">
                    <FiCalendar size={12} className="text-orange-400" />
                    {data.month}
                  </span>
                )}
              </div>
            )}
          </div>

          {/* Rating Badge */}

          {type === "place" && data.rating > 0 && (
            <div className="absolute right-5 top-5 z-20">
              <div className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-black/45 px-4 py-2 backdrop-blur-xl text-white">
                <FiStar className="fill-orange-400 text-orange-400" size={13} />

                <span className="font-bold text-xs">
                  {data.rating.toFixed(1)}
                </span>
              </div>
            </div>
          )}
        </div>

        <div className="flex flex-1 flex-col justify-between p-6 bg-surface transition-colors duration-500">
          <div>
            {/* Festival Location */}

            {type === "festival" && data.stateIds?.[0]?.name && (
              <p className="flex items-center gap-2 text-[11px] font-bold uppercase tracking-[0.18em] text-accent mb-3">
                <FaMapMarkerAlt size={12} />

                {data.stateIds[0].name}
              </p>
            )}

            <h3 className="text-2xl font-extrabold text-primary line-clamp-1 transition-colors duration-300 group-hover:text-accent">
              {name}
            </h3>

            {description && (
              <p className="mt-3 line-clamp-2 text-sm leading-7 text-secondary transition-colors duration-300">
                {description}
              </p>
            )}
          </div>

          <div className="mt-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 text-sm text-muted">
                {(type === "state" || type === "city") &&
                  data.totalPlaces > 0 && (
                    <>
                      <FiCompass className="text-orange-500" />

                      <span>
                        {data.totalPlaces}{" "}
                        {data.totalPlaces === 1
                          ? "Destination"
                          : "Destinations"}
                      </span>
                    </>
                  )}

                {type === "place" && data.category?.name && (
                  <>
                    <FiMapPin className="text-orange-500" />

                    <span>{data.category.name}</span>
                  </>
                )}

                {type === "festival" && data.month && (
                  <>
                    <FiCalendar className="text-orange-500" />

                    <span>{data.month}</span>
                  </>
                )}
              </div>

              {/* Right */}

              <div className="flex items-center gap-2 text-accent font-semibold translate-x-1 group-hover:translate-x-2 transition-transform duration-300">
                <span className="text-sm">Explore</span>

                <FiArrowRight />
              </div>
            </div>
          </div>
        </div>
      </Link>
    </motion.div>
  );
};

export default TravelCard;

import { memo } from "react";
import { FiAlertCircle, FiChevronDown, FiLoader } from "react-icons/fi";
import TravelCardSkeleton from "../cards/TravelCardSkeleton";

const ListingGrid = ({
  items,
  isLoading,
  isError,
  error,
  isFetchingNextPage,
  hasNextPage,
  fetchNextPage,
  CardComponent,
  cardType,
  emptyMessage = "No destinations found"
}) => {
  if (isError) {
    return (
      <div className="bg-red-500/10 border border-red-500/20 rounded-2xl p-8 text-center max-w-2xl mx-auto mb-20">
        <FiAlertCircle className="mx-auto text-red-500 mb-4" size={48} />
        <h3 className="text-xl font-bold text-red-500 mb-2">Failed to load destinations</h3>
        <p className="text-slate-400">{error?.message || "An unexpected error occurred."}</p>
      </div>
    );
  }

  return (
    <div className="px-4 md:px-8 xl:px-12 max-w-[1600px] mx-auto mb-20">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4 gap-8">
        {isLoading ? (
          [...Array(12)].map((_, i) => <TravelCardSkeleton key={i} />)
        ) : items.length === 0 ? (
          <div className="col-span-full py-24 text-center border border-border-glass rounded-[32px] bg-glass-bg backdrop-blur-md">
            <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-surface-elevated mb-6 border border-border-theme">
              <FiAlertCircle className="text-muted" size={32} />
            </div>
            <h3 className="text-2xl font-bold text-primary mb-2">{emptyMessage}</h3>
            <p className="text-muted max-w-md mx-auto">
              Try adjusting your filters or search terms to discover incredible places.
            </p>
          </div>
        ) : (
          items.map((item, index) => (
            <CardComponent
              key={item._id}
              data={item}
              type={cardType}
              index={index % 12}
            />
          ))
        )}

        {/* Skeleton loading when fetching next page */}
        {isFetchingNextPage && (
          [...Array(4)].map((_, i) => <TravelCardSkeleton key={`skeleton-${i}`} />)
        )}
      </div>

      {/* PROGRESSIVE "LOAD MORE" */}
      {!isLoading && hasNextPage && (
        <div className="mt-16 flex justify-center">
          <button
            onClick={() => fetchNextPage()}
            disabled={isFetchingNextPage}
            className="group relative inline-flex items-center justify-center px-10 py-5 font-black text-primary uppercase tracking-[0.15em] text-sm overflow-hidden rounded-[20px] transition-all duration-300 disabled:opacity-50 disabled:pointer-events-none"
          >
            <div className="absolute inset-0 bg-accent/10 border border-accent/30 rounded-[20px] group-hover:bg-accent/20 transition-all duration-300" />
            <div className="absolute inset-0 bg-linear-to-r from-accent/0 via-accent/20 to-accent/0 -translate-x-full group-hover:animate-shimmer" />

            <span className="relative z-10 flex items-center gap-3">
              {isFetchingNextPage ? (
                <>
                  <FiLoader className="animate-spin" size={20} />
                  Loading...
                </>
              ) : (
                <>
                  Explore More Regions
                  <FiChevronDown className="group-hover:translate-y-1 transition-transform" size={18} />
                </>
              )}
            </span>
          </button>
        </div>
      )}

      {/* End of list message */}
      {!isLoading && !hasNextPage && items.length > 0 && (
        <div className="mt-16 text-center">
          <div className="inline-flex items-center gap-3 px-6 py-3 rounded-full bg-surface border border-border-theme shadow-sm">
            <div className="w-2 h-2 rounded-full bg-accent" />
            <p className="text-muted font-bold text-xs uppercase tracking-widest">You've reached the end of the list</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default memo(ListingGrid);

import { motion, useScroll, useTransform } from "framer-motion";
import { memo } from "react";

const ListingHero = ({ heroImage, highlightText, title, subtitle, onScrollClick }) => {
  const { scrollY } = useScroll();
  const y1 = useTransform(scrollY, [0, 500], [0, 150]);
  const opacity1 = useTransform(scrollY, [0, 300], [1, 0]);

  return (
    <div className="relative h-[450px] md:h-[550px] flex flex-col items-center justify-center overflow-hidden">
      {/* Parallax Background Image */}
      <motion.div
        style={{ y: y1, backgroundImage: `url(${heroImage})` }}
        className="absolute inset-0 bg-cover bg-center bg-no-repeat"
      />
      {/* Gradients to seamlessly blend into background */}
      <div className="absolute inset-0 bg-black/40" />
      {/* Gradient Overlay for Text Readability and seamless fade to content */}
      <div className="absolute inset-0 bg-linear-to-b from-black/80 via-transparent to-background" />

      {/* Hero Content */}
      <motion.div
        style={{ opacity: opacity1 }}
        className="relative z-10 text-center px-4 w-full max-w-4xl mx-auto mt-16"
      >
        {highlightText && (
          <span className="inline-block px-4 py-1.5 rounded-full border border-white/20 bg-white/5 backdrop-blur-md text-[#E85D04] font-black tracking-[0.2em] uppercase text-[10px] sm:text-xs mb-6 shadow-xl">
            {highlightText}
          </span>
        )}
        <h1 className="text-4xl md:text-6xl lg:text-7xl font-black text-white mb-6 drop-shadow-2xl leading-[1.1] tracking-tight">
          {title}
        </h1>
        {subtitle && (
          <p className="text-base md:text-xl text-white/80 max-w-2xl mx-auto drop-shadow-lg font-medium leading-relaxed">
            {subtitle}
          </p>
        )}
      </motion.div>

      {/* Scroll Indicator */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1, duration: 1 }}
        className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center cursor-pointer"
        onClick={onScrollClick}
      >
