          <button
            onClick={(e) => { e.stopPropagation(); setConfirmDelete(cityItem._id); }}
            className="flex items-center justify-center p-2 bg-red-50 hover:bg-red-100 dark:bg-red-500/10 dark:hover:bg-red-500/20 text-red-600 dark:text-red-450 rounded-lg transition cursor-pointer"
          >
            <FiTrash2 size={16} />
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <>
      <AdminDataExplorer
        title="Cities Directory"
        subtitle="Create, edit and manage Indian cities registered for TravelBharat explorer guides."
        onAddClick={handleOpenCreate}
        addButtonLabel="Add New City"
        searchPlaceholder="Search cities by name..."
        filters={filters}
        isLoading={isLoading}
        isError={isError}
        error={error}
        items={cities}
        pagination={pagination}
        renderHeader={renderHeader}
        renderRow={renderRow}
        renderGridCard={renderGridCard}
        emptyStateMessage="No cities registered."
      />

      {confirmDelete && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-[#0A121F] border border-slate-200 dark:border-slate-800/60 rounded-2xl p-6 max-w-sm w-full shadow-2xl">
            <h3 className="text-xl font-black text-slate-800 dark:text-white mb-2">Delete City?</h3>
            <p className="text-slate-500 dark:text-slate-400 text-sm mb-6">
              Are you sure you want to delete this city? This action cannot be undone.
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => setConfirmDelete(null)}
                className="flex-1 py-2.5 rounded-xl font-bold text-slate-600 dark:text-slate-300 bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 transition cursor-pointer"
              >
                Cancel
              </button>
              <button
                onClick={() => deleteMutation.mutate(confirmDelete)}
                disabled={deleteMutation.isLoading}
                className="flex-1 py-2.5 rounded-xl font-bold text-white bg-red-600 hover:bg-red-700 transition disabled:opacity-50 cursor-pointer"
              >
                {deleteMutation.isLoading ? "Deleting..." : "Delete"}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Cities;

import { useQuery } from "@tanstack/react-query";
import http from "../../../lib/axios";
import PageLoader from "../../../components/ui/PageLoader";
import { FormHeader } from "../components/form";
import { useCityFormLogic } from "./hooks/useCityFormLogic";
import CityFormFields from "./components/CityFormFields";

const CityForm = () => {
  const {
    id,
    isEditing,
    form,
    setForm,
    isLoading,
    isSaving,
    handleSave,
    uploadingImage,
    uploadSingleImage,
    uploadMultipleImages
  } = useCityFormLogic();

  // Queries for FK relations
  const { data: statesRes } = useQuery({ queryKey: ["adminStatesAll"], queryFn: () => http.get("/states/admin/all?limit=500") });
  const { data: placesRes } = useQuery({ queryKey: ["adminPlacesAll"], queryFn: () => http.get("/places/admin/all?limit=500") });
  const { data: festivalsRes } = useQuery({ queryKey: ["adminFestivalsAll"], queryFn: () => http.get("/festivals/admin/all?limit=500") });
  const { data: foodsRes } = useQuery({ queryKey: ["adminFoodsAll"], queryFn: () => http.get("/foods/admin/all?limit=500") });

  const statesList = statesRes?.data?.data?.states || [];
  const placesList = placesRes?.data?.data?.places || [];
  const festivalsList = festivalsRes?.data?.data?.festivals || [];
  const foodsList = foodsRes?.data?.data?.foods || [];

  const set = (key, value) => {
    setForm(prev => {
      const keys = key.split(".");
      if (keys.length === 1) return { ...prev, [key]: value };
      const [parent, child] = keys;
      return { ...prev, [parent]: { ...prev[parent], [child]: value } };
    });
  };

  const handleArrayString = (key, value) => {
    const arr = value.split(",").map(s => s.trim()).filter(Boolean);
    set(key, arr);
  };

  const onSave = (asDraft) => {
    const payload = {
      ...form,
      isActive: !asDraft,
      mapCoordinates: {
        type: "Point",
        coordinates: [form.mapCoordinates.lng, form.mapCoordinates.lat]
      }
    };
    handleSave(payload);
  };

  const handleImgUpload = async (file, path) => {
    const url = await uploadSingleImage(file, path);
    set(path, url);
  };

  if (isLoading) {
    return <div className="min-h-[60vh] flex items-center justify-center"><PageLoader fullScreen={false} size="md" /></div>;
  }

  return (
    <div className="max-w-6xl mx-auto space-y-5 pb-16 px-4 sm:px-0">
      <FormHeader
        title="City"
        subtitle="Manage city details and attractions"
        backPath="/admin/cities"
        isEditing={isEditing}
        isSaving={isSaving}
        onSave={() => onSave(false)}
        onSaveDraft={() => onSave(true)}
      />

      <CityFormFields 
        form={form} 
        set={set} 
        handleArrayString={handleArrayString}
        handleImgUpload={handleImgUpload}
        uploadingImage={uploadingImage}
        uploadMultipleImages={uploadMultipleImages}
        statesList={statesList}
        placesList={placesList}
        festivalsList={festivalsList}
        foodsList={foodsList}
      />
    </div>
  );
};

export default CityForm;

