              >
                {deleteMutation.isLoading ? "Deleting..." : "Delete"}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Places;

import { useState } from "react";
import { useAuth } from "../../../context/AuthContext";
import { motion } from "framer-motion";
import { FiUser, FiMail, FiPhone, FiCamera, FiShield, FiKey, FiSave, FiMapPin, FiFileText, FiActivity } from "react-icons/fi";
import Button from "../../../components/ui/Button";
import Input from "../../../components/ui/Input";
import { authService } from "../../../services/authService";
import http from "../../../lib/axios";
import { toast } from "react-toastify";

// Motion Variants
const cardVariant = {
  hidden: { opacity: 0, y: 15 },
  show: { opacity: 1, y: 0, transition: { duration: 0.4 } }
};

const Profile = () => {
  const { user, fetchUser } = useAuth();
  
  const [profileData, setProfileData] = useState({
    name: user?.name || "",
    phone: user?.phone || "",
    bio: user?.bio || "",
    state: user?.state || "",
    city: user?.city || "",
  });

  const [passwords, setPasswords] = useState({
    currentPassword: "",
    newPassword: "",
    confirmPassword: ""
  });

  const [uploading, setUploading] = useState(false);
  const [loading, setLoading] = useState(false);
  const [passLoading, setPassLoading] = useState(false);

  const handleProfileUpdate = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await authService.updateProfile(profileData);
      toast.success("Profile updated successfully!");
      fetchUser();
    } catch (error) {
      toast.error(error?.response?.data?.message || "Failed to update profile");
    } finally {
      setLoading(false);
    }
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Client-side file size verification (5MB)
    if (file.size > 5 * 1024 * 1024) {
      return toast.error("Image file size must be less than 5MB");
    }

    setUploading(true);
    const formData = new FormData();
    formData.append("image", file);

    try {
      const uploadRes = await http.post("/upload/single", formData, {
        headers: { "Content-Type": "multipart/form-data" }
      });
      const imageUrl = uploadRes.data.image.url;

      // Immediately save image to user profile
      await authService.updateProfile({ ...profileData, profileImage: imageUrl });
      toast.success("Profile image updated!");
      fetchUser();
    } catch (error) {
      toast.error(error?.response?.data?.message || "Failed to upload image");
    } finally {
      setUploading(false);
    }
  };

  const handlePasswordUpdate = async (e) => {
    e.preventDefault();
    if (passwords.newPassword !== passwords.confirmPassword) {
      return toast.error("New passwords do not match");
    }
    
    setPassLoading(true);
    try {
      await authService.changePassword({
        currentPassword: passwords.currentPassword,
        newPassword: passwords.newPassword
      });
      toast.success("Password changed successfully!");
      setPasswords({ currentPassword: "", newPassword: "", confirmPassword: "" });
    } catch (error) {
      toast.error(error?.response?.data?.message || "Failed to change password");
    } finally {
      setPassLoading(false);
    }
  };

  return (
    <div className="max-w-[1600px] mx-auto space-y-8 pb-16">
      
      {/* Page Header */}
      <div>
        <h1 className="text-3xl font-black text-slate-900 dark:text-white mb-2">Profile & Security</h1>
        <p className="text-slate-500 dark:text-slate-400 text-sm">Manage your administrative credentials, profile bio, avatar, and password logs.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        
        {/* Left Side: Avatar & Information Details */}
        <div className="space-y-6 lg:col-span-1">
          <motion.div 
            variants={cardVariant}
            initial="hidden"
            animate="show"
            className="bg-white dark:bg-[#0A121F] rounded-2xl p-6 shadow-sm border border-slate-200/80 dark:border-slate-800/40 relative overflow-hidden"
          >
            {/* Soft decorative background dot */}
            <div className="absolute -top-10 -right-10 w-32 h-32 bg-[#E85D04]/5 blur-3xl rounded-full" />

            <div className="flex flex-col items-center text-center relative z-10">
              <div className="relative group mb-4">
                <img 
                  src={user?.profileImage || `https://ui-avatars.com/api/?name=${encodeURIComponent(user?.name || "Admin")}&background=E85D04&color=fff&size=128`} 
                  alt="Admin Avatar" 
                  className={`w-32 h-32 rounded-full object-cover border-4 border-slate-100 dark:border-[#0A121F] shadow-lg transition duration-200 ${uploading ? "opacity-40" : ""}`}
                />
                
                {/* Upload overlay */}
                <label className="absolute inset-0 bg-slate-950/60 rounded-full flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition duration-200 cursor-pointer text-white">
                  <FiCamera size={22} className="mb-1" />
                  <span className="text-[10px] font-bold uppercase tracking-wider">{uploading ? "Uploading..." : "Change Image"}</span>
                  <input 
                    type="file" 
                    accept="image/*" 
                    onChange={handleImageUpload} 
                    className="hidden" 
                    disabled={uploading}
                  />
                </label>
              </div>

              <h2 className="text-xl font-bold text-slate-900 dark:text-white">{user?.name || "Administrator"}</h2>
              <span className="mt-1 text-xs uppercase tracking-wider font-extrabold text-[#E85D04] dark:text-[#FFA034] bg-[#E85D04]/10 px-3 py-1 rounded-full border border-[#E85D04]/20">
                {user?.role || "Admin"} Account
              </span>

              {/* Quick Info Grid */}
              <div className="w-full flex flex-col gap-3 text-sm text-left text-slate-600 dark:text-slate-400 border-t border-slate-100 dark:border-slate-800/40 mt-6 pt-5">
                <div className="flex items-center gap-3">
                  <FiMail className="text-slate-400 shrink-0" size={16} />
                  <span className="truncate">{user?.email}</span>
                </div>
                <div className="flex items-center gap-3">
                  <FiShield className="text-slate-400 shrink-0" size={16} />
                  <span className="capitalize">{user?.authProvider || "Local"} Session provider</span>
                </div>
                {user?.phone && (
                  <div className="flex items-center gap-3">
                    <FiPhone className="text-slate-400 shrink-0" size={16} />
                    <span>{user.phone}</span>
                  </div>
                )}
              </div>
            </div>
          </motion.div>

          {/* Activity Section */}
          <motion.div
            variants={cardVariant}
            initial="hidden"
            animate="show"
            className="bg-white dark:bg-[#0A121F] rounded-2xl p-6 shadow-sm border border-slate-200/80 dark:border-slate-800/40"
          >
            <h3 className="text-sm uppercase tracking-wider font-bold text-slate-400 mb-4 flex items-center gap-2">
              <FiActivity size={16} className="text-[#E85D04]" />
              <span>Activity Status</span>
            </h3>

            <div className="space-y-4 text-xs font-semibold">
              <div className="flex justify-between items-center py-2 border-b border-slate-100 dark:border-slate-800/45">
                <span className="text-slate-400">Account status</span>
                <span className="text-emerald-500 flex items-center gap-1.5">
                  <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                  Active
                </span>
              </div>
              <div className="flex justify-between items-center py-2">
                <span className="text-slate-400">Created date</span>
                <span className="text-slate-700 dark:text-slate-350">
                  {user?.createdAt ? new Date(user.createdAt).toLocaleDateString() : "N/A"}
                </span>
              </div>
            </div>
          </motion.div>
        </div>

        {/* Right Side: Configuration Forms */}
        <div className="lg:col-span-2 space-y-8">
          
          {/* Section 1: Profile Information */}
          <motion.div
            variants={cardVariant}
            initial="hidden"
            animate="show"
            className="bg-white dark:bg-[#0A121F] rounded-2xl p-6 sm:p-8 shadow-sm border border-slate-200/80 dark:border-slate-800/40 space-y-6"
          >
            <div className="flex items-center gap-3.5 pb-4 border-b border-slate-100 dark:border-slate-800/40">
              <div className="w-10 h-10 rounded-xl bg-[#E85D04]/10 flex items-center justify-center text-[#E85D04]">
                <FiUser size={20} />
              </div>
              <div>
                <h3 className="text-lg font-bold text-slate-900 dark:text-white">Admin Details</h3>
                <p className="text-xs text-slate-400">Update your public credentials and descriptions</p>
              </div>
            </div>

            <form onSubmit={handleProfileUpdate} className="space-y-5">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <Input
                  label="name"
                  labelName="Full Name"
                  icon={FiUser}
                  type="text"
                  placeholder="Enter name"
                  value={profileData.name}
                  onChange={(e) => setProfileData({ ...profileData, name: e.target.value })}
                  required
                />
                <Input
                  label="phone"
                  labelName="Phone Number"
                  icon={FiPhone}
                  type="text"
                  placeholder="Enter contact number"
                  value={profileData.phone}
                  onChange={(e) => setProfileData({ ...profileData, phone: e.target.value })}
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <Input
                  label="city"
                  labelName="City Location"
                  icon={FiMapPin}
                  type="text"
                  placeholder="Enter city"
                  value={profileData.city}
                  onChange={(e) => setProfileData({ ...profileData, city: e.target.value })}
                />
                <Input
                  label="state"
                  labelName="State Location"
                  icon={FiMapPin}
                  type="text"
                  placeholder="Enter state"
                  value={profileData.state}
                  onChange={(e) => setProfileData({ ...profileData, state: e.target.value })}
                />
              </div>

              <div className="flex flex-col gap-1.5 w-full">
                <label className="text-sm font-semibold text-slate-500 dark:text-slate-400 ml-0.5 flex items-center gap-1.5">
                  <FiFileText size={14} />
                  <span>Bio Description</span>
                </label>
                <textarea
                  rows={4}
                  value={profileData.bio}
                  onChange={(e) => setProfileData({ ...profileData, bio: e.target.value })}
                  placeholder="Tell explorers something about yourself or your travel expertise..."
                  className="w-full px-4 py-3 rounded-xl border border-slate-300 dark:border-slate-800 bg-transparent text-slate-900 dark:text-slate-100 focus:outline-hidden focus:ring-2 focus:ring-[#E85D04]/20 focus:border-[#E85D04] text-sm transition"
                />
              </div>

              <div className="flex justify-end pt-2">
                <Button 
                  type="submit" 
                  disabled={loading} 
                  className="flex items-center gap-2 px-6 py-2.5 bg-[#E85D04] hover:bg-[#D05203] text-white font-bold rounded-xl cursor-pointer transition shadow-xs"
                >
                  <FiSave size={16} /> 
                  <span>{loading ? "Saving Changes..." : "Save Changes"}</span>
                </Button>
              </div>
            </form>
          </motion.div>

          {/* Section 2: Password Update */}
          {user?.authProvider !== "google" && (
            <motion.div
              variants={cardVariant}
              initial="hidden"
              animate="show"
              className="bg-white dark:bg-[#0A121F] rounded-2xl p-6 sm:p-8 shadow-sm border border-slate-200/80 dark:border-slate-800/40 space-y-6"
            >
              <div className="flex items-center gap-3.5 pb-4 border-b border-slate-100 dark:border-slate-800/40">
                <div className="w-10 h-10 rounded-xl bg-[#E85D04]/10 flex items-center justify-center text-[#E85D04]">
                  <FiKey size={20} />
                </div>
                <div>
                  <h3 className="text-lg font-bold text-slate-900 dark:text-white">Change Password</h3>
                  <p className="text-xs text-slate-400">Regularly updates protect server admin access</p>
                </div>
              </div>

              <form onSubmit={handlePasswordUpdate} className="space-y-5">
                <Input
                  label="currentPassword"
                  labelName="Current Password"
                  icon={FiKey}
                  type="password"
                  placeholder="Enter current password"
                  value={passwords.currentPassword}
                  onChange={(e) => setPasswords({ ...passwords, currentPassword: e.target.value })}
                  required
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                  <Input
                    label="newPassword"
                    labelName="New Password"
                    icon={FiKey}
                    type="password"
                    placeholder="Min 6 characters"
                    value={passwords.newPassword}
                    onChange={(e) => setPasswords({ ...passwords, newPassword: e.target.value })}
                    required
                    minLength={6}
                  />
                  <Input
                    label="confirmPassword"
                    labelName="Confirm New Password"
                    icon={FiKey}
                    type="password"
                    placeholder="Retype new password"
                    value={passwords.confirmPassword}
                    onChange={(e) => setPasswords({ ...passwords, confirmPassword: e.target.value })}
                    required
                    minLength={6}
                  />
                </div>

                <div className="flex justify-end pt-2">
                  <Button 
                    type="submit" 
                    disabled={passLoading}
                    className="flex items-center gap-2 px-6 py-2.5 bg-[#E85D04] hover:bg-[#D05203] text-white font-bold rounded-xl cursor-pointer transition shadow-xs"
                  >
                    <FiKey size={16} />
                    <span>{passLoading ? "Updating Password..." : "Update Password"}</span>
                  </Button>
                </div>
              </form>
            </motion.div>
          )}

        </div>
      </div>
    </div>
  );
};

export default Profile;

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useSearchParams, useNavigate } from "react-router-dom";
import { FiStar, FiCheck, FiX, FiTrash2, FiMessageSquare, FiMapPin, FiUser, FiClock, FiGrid, FiList } from "react-icons/fi";
import http from "../../../lib/axios";
import SearchAndFilter from "../../../components/ui/SearchAndFilter";
import AdminPageLayout from "../components/ui/AdminPageLayout";
import AdminPagination from "../components/ui/AdminPagination";
import { toast } from "react-toastify";

import { useAdminList } from "../hooks/useAdminList";
import { useAdminMutations } from "../hooks/useAdminMutations";

const Reviews = () => {
  const queryClient = useQueryClient();
  const navigate = useNavigate();

  const [responseModal, setResponseModal] = useState(null);
  const [adminReplyText, setAdminReplyText] = useState("");
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [viewMode, setViewMode] = useState(() => localStorage.getItem("adminReviewsViewMode") || "list");

  useEffect(() => {
    localStorage.setItem("adminReviewsViewMode", viewMode);
  }, [viewMode]);

  const { data, isLoading, isError, error, searchParams, setSearchParams } = useAdminList({
    queryKey: "adminReviews",
    endpoint: "/reviews/admin/all",
    extractParams: (params) => ({
      status: params.get("status") || ""
    })
  });

  const { deleteMutation } = useAdminMutations({
    queryKey: ["adminReviews"],
    updateEndpoint: (id) => `/reviews/admin/${id}`,
    deleteEndpoint: (id) => `/reviews/admin/${id}`,
    successDeleteMsg: "Review deleted permanently!"
  });

  const responseData = data?.data || {};
  const reviews = responseData.reviews || [];
  const pagination = responseData.pagination || { total: 0, pages: 1 };

  const approveMutation = useMutation({
    mutationFn: async (id) => {
      const response = await http.put(`/reviews/admin/approve/${id}`);
      return response.data;
    },
    onSuccess: () => {
      toast.success("Review approved successfully!");
      queryClient.invalidateQueries(["adminReviews"]);
    },
    onError: (err) => {
      toast.error(err?.response?.data?.message || "Approval failed");
    }
  });

  const rejectMutation = useMutation({
    mutationFn: async (id) => {
      const response = await http.put(`/reviews/admin/reject/${id}`);
      return response.data;
    },
    onSuccess: () => {
      toast.success("Review rejected & hidden.");
      queryClient.invalidateQueries(["adminReviews"]);
    },
    onError: (err) => {
      toast.error(err?.response?.data?.message || "Rejection failed");
    }
  });

  const respondMutation = useMutation({
    mutationFn: async ({ id, text }) => {
      const response = await http.put(`/reviews/admin/respond/${id}`, { adminResponse: text });
      return response.data;
    },
    onSuccess: () => {
      toast.success("Response posted successfully!");
      setResponseModal(null);
      setAdminReplyText("");
      queryClient.invalidateQueries(["adminReviews"]);
    },
    onError: (err) => {
      toast.error(err?.response?.data?.message || "Failed to post reply");
    }
  });

  const handleRespondClick = (e, review) => {
    e.stopPropagation();
    setResponseModal(review);
    setAdminReplyText(review.adminResponse || "");
  };

  const handleRespondSubmit = (e) => {
    e.preventDefault();
    if (!adminReplyText.trim()) return;
    respondMutation.mutate({ id: responseModal._id, text: adminReplyText.trim() });
  };

  const handleRowClick = (review) => {
    navigate(`/admin/reviews/${review._id}`);
  };

  const filters = [
    {
      key: "status",
      label: "Moderation State",
      options: [
        { value: "pending", label: "Awaiting Approval" },
        { value: "approved", label: "Approved" }
      ]
    }
  ];

  return (
    <AdminPageLayout
      title="Review Management"
      subtitle="Approve, reject, respond to user feedback, and moderate rating metrics for destinations."
      actions={
        <div className="hidden sm:flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
          <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition cursor-pointer ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}><FiList size={16} /></button>
          <button onClick={() => setViewMode('grid')} className={`p-2 rounded-lg transition cursor-pointer ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}><FiGrid size={16} /></button>
        </div>
      }
    >
      <SearchAndFilter
        searchPlaceholder="Filter items..."
        filters={filters}
      />

      <div className="bg-transparent">
        {viewMode === "list" && (
        <div className="bg-white dark:bg-[#0A121F] border border-slate-200/80 dark:border-slate-800/40 rounded-2xl shadow-sm overflow-hidden mb-6">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-slate-100 dark:border-slate-800/60 bg-slate-55/40 dark:bg-slate-900/10 text-slate-400 text-xs font-extrabold uppercase tracking-wider">
                <th className="py-4 px-6">Traveler / Date</th>
                <th className="py-4 px-6">Destination</th>
                <th className="py-4 px-6">Feedback / Comments</th>
                <th className="py-4 px-6">Rating</th>
                <th className="py-4 px-6">Status</th>
                <th className="py-4 px-6 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800/30 text-sm text-slate-655 dark:text-slate-350">
              {isLoading ? (
                [...Array(5)].map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    <td className="py-4 px-6">
                      <div className="flex items-center gap-2">
                        <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-800" />
                        <div className="space-y-1">
                          <div className="w-20 h-3.5 bg-slate-200 dark:bg-slate-800 rounded" />
                          <div className="w-28 h-2.5 bg-slate-200 dark:bg-slate-800 rounded" />
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-6"><div className="w-24 h-4 bg-slate-200 dark:bg-slate-800 rounded" /></td>
                    <td className="py-4 px-6"><div className="w-44 h-4 bg-slate-200 dark:bg-slate-800 rounded" /></td>
                    <td className="py-4 px-6"><div className="w-16 h-4 bg-slate-200 dark:bg-slate-800 rounded" /></td>
                    <td className="py-4 px-6"><div className="w-16 h-5 bg-slate-200 dark:bg-slate-800 rounded-full" /></td>
                    <td className="py-4 px-6 text-right"><div className="w-16 h-6 bg-slate-200 dark:bg-slate-800 rounded ml-auto" /></td>
                  </tr>
                ))
              ) : isError ? (
                <tr>
                  <td colSpan="6" className="text-center py-10 text-red-500 font-bold">
                    Error loading reviews: {error?.message}
                  </td>
                </tr>
              ) : reviews.length === 0 ? (
                <tr>
                  <td colSpan="6" className="text-center py-12 text-slate-400 font-semibold">
                    <FiStar size={36} className="mx-auto mb-3 text-slate-300" />
                    No traveler reviews found under selected criteria.
                  </td>
                </tr>
              ) : (
                reviews.map((review) => (
                  <tr 
                    key={review._id} 
                    onClick={() => handleRowClick(review)}
                    className="hover:bg-slate-50/50 dark:hover:bg-slate-850/5 transition cursor-pointer"
                  >
                    <td className="py-4 px-6">
                      <div className="flex items-center gap-2.5">
                        {review.userId?.profileImage ? (
                          <img
                            src={review.userId.profileImage?.url || review.userId.profileImage}
                            alt={review.userId.name}
                            className="w-8 h-8 rounded-full object-cover shrink-0 border border-slate-200 dark:border-slate-850"
                          />
                        ) : (
                          <div className="w-8 h-8 rounded-full bg-[#E85D04]/10 text-[#E85D04] text-[10px] font-bold flex items-center justify-center shrink-0">
                            {review.userId?.name ? review.userId.name[0].toUpperCase() : <FiUser />}
                          </div>
                        )}
                        <div className="min-w-0">
                          <p className="text-xs font-bold truncate max-w-[120px]">{review.userId?.name || "Guest Traveler"}</p>
                          <span className="text-[10px] text-slate-400 flex items-center gap-1">
                            <FiClock size={10} />
                            {new Date(review.createdAt).toLocaleDateString()}
                          </span>
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-6 font-semibold">
                      <div className="flex items-center gap-1.5 text-xs">
                        <FiMapPin className="text-[#E85D04] shrink-0" size={14} />
                        <span className="truncate max-w-[150px]">{review.placeId?.name || "Deleted Destination"}</span>
                      </div>
                    </td>
                    <td className="py-4 px-6">
                      <div className="max-w-[280px]">
                        {review.title && <h5 className="font-extrabold text-xs text-slate-800 dark:text-slate-200 mb-0.5 truncate">{review.title}</h5>}
                        <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 leading-relaxed">
                          {review.comment}
                        </p>
                        {review.adminResponse && (
                          <div className="mt-1.5 p-2 bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-850/50 rounded-lg text-[10px] italic text-[#E85D04] dark:text-[#FFA034]">
                            <span className="font-bold uppercase tracking-wider not-italic mr-1 text-[9px] bg-[#E85D04]/15 px-1.5 py-0.5 rounded-sm">Reply:</span>
                            {review.adminResponse}
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="py-4 px-6">
                      <div className="flex items-center gap-0.5 text-amber-500">
                        {[...Array(5)].map((_, i) => (
                          <FiStar
                            key={i}
                            size={12}
                            className={i < review.rating ? "fill-amber-500" : "text-slate-200 dark:text-slate-800"}
                          />
                        ))}
                      </div>
                    </td>
                    <td className="py-4 px-6">
                      <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${
                        review.isApproved
                          ? "bg-emerald-500/10 text-emerald-600 dark:text-emerald-450"
                          : "bg-amber-500/10 text-amber-600 dark:text-amber-500"
                      }`}>
                        {review.isApproved ? "Approved" : "Pending Approval"}
                      </span>
                    </td>
                    <td className="py-4 px-6 text-right">
                      <div className="flex items-center justify-end gap-2">
                        {!review.isApproved ? (
                          <button
                            onClick={(e) => { e.stopPropagation(); approveMutation.mutate(review._id); }}
                            title="Approve & Publish"
                            className="p-2 text-slate-400 hover:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-500/10 rounded-xl transition cursor-pointer"
                          >
                            <FiCheck size={16} />
                          </button>
                        ) : (
                          <button
                            onClick={(e) => { e.stopPropagation(); rejectMutation.mutate(review._id); }}
                            title="Reject & Hide"
                            className="p-2 text-slate-400 hover:text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-500/10 rounded-xl transition cursor-pointer"
                          >
                            <FiX size={16} />
                          </button>
                        )}
                        <button
                          onClick={(e) => handleRespondClick(e, review)}
                          title="Write administrative response"
                          className="p-2 text-slate-400 hover:text-[#E85D04] hover:bg-orange-50 dark:hover:bg-[#E85D04]/10 rounded-xl transition cursor-pointer"
                        >
                          <FiMessageSquare size={16} />
                        </button>
                        <button
                          onClick={(e) => { e.stopPropagation(); setConfirmDelete(review._id); }}
                          title="Delete permanently"
                          className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-xl transition cursor-pointer"
                        >
                          <FiTrash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
        </div>
        )}

        {viewMode === "grid" && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 p-6">
            {isLoading ? (
              [...Array(8)].map((_, i) => (
                <div key={i} className="bg-slate-100 dark:bg-slate-800/50 border border-slate-200/80 dark:border-slate-800/40 rounded-2xl shadow-sm p-4 animate-pulse h-64" />
              ))
            ) : isError ? (
              <div className="col-span-full text-center py-10 text-red-500 font-bold">Error loading reviews</div>
            ) : reviews.length === 0 ? (
              <div className="col-span-full text-center py-12 text-slate-400 font-semibold">No traveler reviews found under selected criteria.</div>
            ) : (
              reviews.map((review) => (
                <div 
                  key={review._id} 
                  onClick={() => handleRowClick(review)}
                  className="bg-white dark:bg-[#0A121F] border border-slate-200/80 dark:border-slate-800/40 rounded-2xl shadow-sm overflow-hidden hover:shadow-lg transition flex flex-col group cursor-pointer p-5 relative"
                >
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex items-center gap-2">
                      {review.userId?.profileImage ? (
                        <img src={review.userId.profileImage?.url || review.userId.profileImage} alt={review.userId.name} className="w-8 h-8 rounded-full object-cover shrink-0 border border-slate-200 dark:border-slate-850" />
                      ) : (
                        <div className="w-8 h-8 rounded-full bg-[#E85D04]/10 text-[#E85D04] text-[10px] font-bold flex items-center justify-center shrink-0">
                          {review.userId?.name ? review.userId.name[0].toUpperCase() : <FiUser />}
                        </div>
                      )}
                      <div className="min-w-0">
                        <p className="text-xs font-bold truncate max-w-[120px]">{review.userId?.name || "Guest Traveler"}</p>
                        <span className="text-[10px] text-slate-400 flex items-center gap-1">
                          <FiClock size={10} />
                          {new Date(review.createdAt).toLocaleDateString()}
                        </span>
                      </div>
                    </div>
                    <span className={`inline-flex items-center px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider ${
                      review.isApproved ? "bg-emerald-500/10 text-emerald-600 dark:text-emerald-450" : "bg-amber-500/10 text-amber-600 dark:text-amber-500"
                    }`}>
                      {review.isApproved ? "Approved" : "Pending"}
                    </span>
                  </div>

                  <div className="flex items-center gap-1.5 text-xs font-semibold mb-3">
                    <FiMapPin className="text-[#E85D04] shrink-0" size={14} />
                    <span className="truncate max-w-[150px]">{review.placeId?.name || "Deleted Destination"}</span>
                  </div>

                  <div className="flex items-center gap-0.5 text-amber-500 mb-3">
                    {[...Array(5)].map((_, i) => (
                      <FiStar key={i} size={12} className={i < review.rating ? "fill-amber-500" : "text-slate-200 dark:text-slate-800"} />
                    ))}
                  </div>

                  <div className="flex-1 mb-4">
                    {review.title && <h5 className="font-extrabold text-xs text-slate-800 dark:text-slate-200 mb-0.5 truncate">{review.title}</h5>}
                    <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-3 leading-relaxed">
                      {review.comment}
                    </p>
                    {review.adminResponse && (
                      <div className="mt-2 p-2 bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-850/50 rounded-lg text-[10px] italic text-[#E85D04] dark:text-[#FFA034] line-clamp-2">
                        <span className="font-bold uppercase tracking-wider not-italic mr-1 text-[9px] bg-[#E85D04]/15 px-1.5 py-0.5 rounded-sm">Reply:</span>
                        {review.adminResponse}
                      </div>
                    )}
                  </div>

                  <div className="mt-auto pt-3 border-t border-slate-100 dark:border-slate-800/50 flex items-center justify-between">
                    <div className="flex gap-1">
                      {!review.isApproved ? (
                        <button onClick={(e) => { e.stopPropagation(); approveMutation.mutate(review._id); }} className="p-1.5 text-slate-400 hover:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-500/10 rounded-lg transition cursor-pointer"><FiCheck size={14} /></button>
                      ) : (
                        <button onClick={(e) => { e.stopPropagation(); rejectMutation.mutate(review._id); }} className="p-1.5 text-slate-400 hover:text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-500/10 rounded-lg transition cursor-pointer"><FiX size={14} /></button>
                      )}
                      <button onClick={(e) => handleRespondClick(e, review)} className="p-1.5 text-slate-400 hover:text-[#E85D04] hover:bg-orange-50 dark:hover:bg-[#E85D04]/10 rounded-lg transition cursor-pointer"><FiMessageSquare size={14} /></button>
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); setConfirmDelete(review._id); }} className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg transition cursor-pointer"><FiTrash2 size={14} /></button>
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        <AdminPagination isLoading={isLoading} isError={isError} pagination={pagination} />
      </div>

      {responseModal && (
        <div className="fixed inset-0 bg-slate-955/60 backdrop-blur-xs flex items-center justify-center p-4 z-50 animate-fadeIn">
          <div className="bg-white dark:bg-[#0A121F] border border-slate-200 dark:border-slate-800 rounded-2xl max-w-lg w-full p-6 shadow-2xl animate-scaleIn">
            <div className="flex justify-between items-center pb-3 border-b border-slate-100 dark:border-slate-800/40 mb-4">
              <h3 className="text-lg font-bold text-slate-900 dark:text-white">Admin Response</h3>
              <button onClick={() => setResponseModal(null)} className="p-1 rounded-full text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 cursor-pointer">
                <FiX size={18} />
              </button>
            </div>

            <form onSubmit={handleRespondSubmit} className="space-y-4">
              <div className="p-3.5 bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-850 rounded-xl text-xs text-slate-500">
                <p className="font-bold text-slate-700 dark:text-slate-300 mb-1">
                  Review by {responseModal.userId?.name || "Guest"}:
                </p>
                <p className="italic">"{responseModal.comment}"</p>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-500 dark:text-slate-400 mb-1.5">Your Response</label>
                <textarea
                  rows={4}
                  required
                  value={adminReplyText}
                  onChange={(e) => setAdminReplyText(e.target.value)}
                  placeholder="Thank you for sharing your feedback with the community! We appreciate..."
                  className="w-full px-4 py-2.5 border border-slate-350 dark:border-slate-800 rounded-xl bg-transparent text-sm focus:outline-hidden focus:ring-2 focus:ring-[#E85D04]/20 focus:border-[#E85D04]"
                />
              </div>

              <div className="flex justify-end gap-3 pt-3">
                <button
                  type="button"
                  onClick={() => setResponseModal(null)}
                  className="px-4 py-2 border border-slate-250 dark:border-slate-800 text-slate-650 dark:text-slate-305 font-semibold rounded-xl text-sm hover:bg-slate-50 dark:hover:bg-slate-850 transition cursor-pointer"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={respondMutation.isLoading}
                  className="px-5 py-2 bg-[#E85D04] hover:bg-[#D05203] text-white font-bold rounded-xl text-sm transition"
                >
                  Submit Reply
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {confirmDelete && (
        <div className="fixed inset-0 bg-slate-955/60 backdrop-blur-xs flex items-center justify-center p-4 z-50 animate-fadeIn">
          <div className="bg-white dark:bg-[#0A121F] border border-slate-200 dark:border-slate-850 rounded-2xl max-w-md w-full p-6 shadow-2xl animate-scaleIn">
            <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">Delete Review?</h3>
            <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">
              Deleting this review will remove it permanently and update the destination's average rating scores. This action cannot be undone.
            </p>
            <div className="flex justify-end gap-3">
              <button
                onClick={() => setConfirmDelete(null)}
                className="px-4 py-2 border border-slate-250 dark:border-slate-800 text-slate-650 dark:text-slate-305 font-semibold rounded-xl text-sm hover:bg-slate-50 dark:hover:bg-slate-850 transition"
              >
                Cancel
              </button>
              <button
                onClick={() => deleteMutation.mutate(confirmDelete)}
                className="px-5 py-2 bg-red-500 hover:bg-red-655 text-white font-bold rounded-xl text-sm transition"
              >
                Delete Review
              </button>
            </div>
          </div>
        </div>
      )}
    </AdminPageLayout>
  );
};

export default Reviews;

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useSearchParams, useNavigate } from "react-router-dom";
import { FiImage, FiEdit, FiTrash2, FiStar, FiMapPin } from "react-icons/fi";
import http from "../../../lib/axios";
import { toast } from "react-toastify";
import AdminDataExplorer from "../components/ui/AdminDataExplorer";

import { useAdminList } from "../hooks/useAdminList";
import { useAdminMutations } from "../hooks/useAdminMutations";

const States = () => {
  const queryClient = useQueryClient();
  const navigate = useNavigate();

  const [confirmDelete, setConfirmDelete] = useState(null);

  // Query
  const { data, isLoading, isError, error, searchParams, setSearchParams } = useAdminList({
    queryKey: "adminStates",
    endpoint: "/states/admin/all",
    extractParams: (params) => ({
      region: params.get("region") || "",
      featured: params.get("featured") || ""
    })
  });

  const { deleteMutation, toggleStatus, updateMutation } = useAdminMutations({
    queryKey: ["adminStates"],
    updateEndpoint: (id) => `/states/admin/${id}`,
    deleteEndpoint: (id) => `/states/admin/${id}`,
    successDeleteMsg: "State deleted permanently!"
  });

  const states = data?.data?.items || [];
  const pagination = {
    total: data?.data?.totalItems || 0,
    pages: data?.data?.totalPages || 1
  };

  const handleEditClick = (stateItem) => navigate(`/admin/states/edit/${stateItem._id}`);
  const handleOpenCreate = () => navigate("/admin/states/create");

  const handleToggleFeatured = (stateItem) => {
    updateMutation.mutate({ id: stateItem._id, payload: { featured: !stateItem.featured } });
  };

  const handleToggleActive = (stateItem) => toggleStatus(stateItem._id, stateItem.isActive);

  const renderHeader = () => (
    <>
      <th className="py-4 px-6">State / Tagline</th>
      <th className="py-4 px-6">Capital</th>
      <th className="py-4 px-6">Region</th>
      <th className="py-4 px-6">Featured</th>
      <th className="py-4 px-6">Status</th>
      <th className="py-4 px-6 text-right">Actions</th>
    </>
  );

  const renderRow = (stateItem) => (
    <tr 
      key={stateItem._id} 
      onClick={() => navigate(`/admin/states/${stateItem._id}`)}
      className="hover:bg-slate-50/50 dark:hover:bg-slate-900/70 transition cursor-pointer"
    >
      <td className="py-4 px-6">
        <div className="flex items-center gap-4">
          {stateItem.images?.thumbnail ? (
            <img
              src={stateItem.images.thumbnail?.url || stateItem.images.thumbnail}
              alt={stateItem.name}
              className="w-12 h-12 rounded-lg object-cover bg-slate-100 shrink-0"
            />
          ) : (
            <div className="w-12 h-12 rounded-lg bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-400 shrink-0">
              <FiImage size={20} />
            </div>
          )}
          <div>
            <h4 className="font-bold text-slate-800 dark:text-slate-200">{stateItem.name}</h4>
            <span className="text-xs text-slate-400 truncate max-w-[200px] block">{stateItem.tagline}</span>
          </div>
        </div>
      </td>
      <td className="py-4 px-6 font-semibold">{stateItem.capital || "—"}</td>
      <td className="py-4 px-6 font-semibold capitalize text-xs text-slate-400">{stateItem.region} India</td>
      <td className="py-4 px-6">
        <button
          onClick={(e) => { e.stopPropagation(); handleToggleFeatured(stateItem); }}
          className={`p-1.5 rounded-lg border transition duration-200 cursor-pointer ${stateItem.featured
              ? "bg-amber-500/10 border-amber-500/20 text-amber-500"
              : "border-slate-200 dark:border-slate-800 text-slate-300 hover:text-slate-500"
            }`}
        >
          <FiStar size={16} className={stateItem.featured ? "fill-amber-500" : ""} />
        </button>
      </td>
      <td className="py-4 px-6">
        <button
          onClick={(e) => { e.stopPropagation(); handleToggleActive(stateItem); }}
          className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold transition cursor-pointer ${stateItem.isActive
              ? "bg-emerald-500/10 text-emerald-600 dark:text-emerald-450 hover:bg-emerald-500/20"
              : "bg-red-500/10 text-red-650 dark:text-red-400 hover:bg-red-500/20"
            }`}
        >
          {stateItem.isActive ? "Active" : "Hidden"}
        </button>
      </td>
      <td className="py-4 px-6 text-right">
        <div className="flex items-center justify-end gap-2">
          <button
            onClick={(e) => { e.stopPropagation(); handleEditClick(stateItem); }}
            className="p-2 text-slate-400 hover:text-slate-800 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition cursor-pointer"
          >
