import { NavLink, useLocation, useNavigate } from "react-router-dom";
import { FiUser, FiMenu, FiX, FiMoon, FiSun, FiChevronDown, FiMapPin, FiBell } from "react-icons/fi";
import { useState, useEffect, memo } from "react";
import { useAuth } from "../../context/AuthContext";
import { navLinks } from "../../features/public/data/routes/public.routes";
import Button from "../../components/ui/Button";
import UserDropdown from "../../components/ui/UserDropdown";
import AuthSkeleton from "../../components/feedback/skeleton/AuthSkeleton";
import MobileAuthSkeleton from "../../components/feedback/skeleton/MobileAuthSkeleton";
import LogoutButton from "../../components/ui/LogoutButton";
import logoDark from "../../assets/logo_dark.png";
import logoLight from "../../assets/logo_light.png";
import { useQuery } from "@tanstack/react-query";
import http from "../../lib/axios";
import { useTheme } from "../../hooks/useTheme";

const Navbar = memo(() => {
  const [menuOpen, setMenuOpen] = useState(false);
  const [userOpen, setUserOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const { user, loading } = useAuth();
  const location = useLocation();
  const { theme, toggleTheme } = useTheme();

  const { data: notifData } = useQuery({
    queryKey: ["userNotifications"],
    queryFn: async () => {
      const res = await http.get("/notifications/user");
      return res.data?.data || res.data;
    },
    enabled: !!user && user.role === "user"
  });

  const unreadCount = notifData?.unreadCount || 0;

  const isHome = location.pathname === "/";

  // Handle scroll for transparent-to-solid navbar effect
  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  useEffect(() => {
    setMenuOpen(false);
  }, [location.pathname]);

  const navClass = isHome && !scrolled && !menuOpen
    ? "bg-transparent text-primary"
    : "glass text-primary";

  const activeLinks = ({ isActive }) =>
    `p-2 font-medium transition duration-300 ${isActive
      ? "border-b-2 border-[#E85D04] text-[#E85D04]"
      : "hover:text-[#E85D04]"
    }`;

  const DesktopAuthButtons = () => {
    if (loading) return <AuthSkeleton />;

    if (!user) {
      return (
        <NavLink to="/auth">
          <Button variant="primary">
            <FiUser size={18} /> Sign In
          </Button>
        </NavLink>
      );
    }

    return (
      <div className="flex items-center gap-3">
        {user?.role === "admin" && (
          <NavLink to="/admin/dashboard" title="Go to Admin Panel">
            <Button variant="danger" className="cursor-pointer">Admin Panel</Button>
          </NavLink>
        )}

        {user?.role === "user" && (
          <div className="flex items-center gap-4">
            <NavLink to="/user/notifications" className="relative p-2 text-slate-600 dark:text-slate-300 hover:text-[#E85D04] transition-colors rounded-full hover:bg-slate-100 dark:hover:bg-slate-800">
              <FiBell size={22} />
              {unreadCount > 0 && (
                <span className="absolute top-1 right-1 w-4 h-4 bg-red-500 text-white text-[10px] font-bold flex items-center justify-center rounded-full border border-white dark:border-[#0A1628]">
                  {unreadCount > 9 ? "9+" : unreadCount}
                </span>
              )}
            </NavLink>
            <div className="relative">
              <button
                onClick={() => setUserOpen((prev) => !prev)}
                className="flex items-center justify-center gap-2 px-3 py-2 rounded-lg bg-slate-100/50 dark:bg-slate-800/50 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors cursor-pointer"
              >
                <div className="w-8 h-8 rounded-full bg-[#E85D04] text-white flex items-center justify-center font-bold text-sm">
                  {user.name.charAt(0).toUpperCase()}
                </div>
                <span className="font-medium hidden lg:block">{user.name}</span>
                <FiChevronDown size={16} />
              </button>
              <UserDropdown open={userOpen} setOpen={setUserOpen} />
            </div>
          </div>
        )}
      </div>
    );
  };

  const MobileAuthButtons = () => {
    if (loading) return <MobileAuthSkeleton />;

    if (!user) {
      return (
        <NavLink to="/auth" className="w-full">
          <Button className="w-full">
            <FiUser size={18} /> Sign In
          </Button>
        </NavLink>
      );
    }

    return (
      <div className="flex flex-col gap-3 mt-4 pt-4 border-t border-slate-200 dark:border-slate-800">
        <div className="flex items-center gap-3 mb-2">
          <div className="w-10 h-10 rounded-full bg-[#E85D04] text-white flex items-center justify-center font-bold">
            {user.name.charAt(0).toUpperCase()}
          </div>
          <div>
            <p className="font-bold text-slate-800 dark:text-white">{user.name}</p>
            <p className="text-xs text-slate-500">{user.email}</p>
          </div>
        </div>

        {user?.role === "admin" && (
          <NavLink to="/admin/dashboard">
            <Button variant="secondary" className="w-full">Admin Dashboard</Button>
          </NavLink>
        )}

        {user?.role === "user" && (
          <>
            <NavLink to="/user/notifications">
              <Button variant="ghost" className="w-full justify-between items-center text-left">
                <span className="flex items-center gap-2">Notifications</span>
                {unreadCount > 0 && (
                  <span className="bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full">
                    {unreadCount > 9 ? "9+" : unreadCount}
                  </span>
                )}
              </Button>
            </NavLink>
            <NavLink to="/user/profile">
              <Button variant="ghost" className="w-full justify-start">My Profile</Button>
            </NavLink>
          </>
        )}

        <LogoutButton className="w-full mt-2" />
      </div>
    );
  };

  return (
    <>
      <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${navClass}`}>
        <nav className="max-w-[1600px] w-full mx-auto flex items-center justify-between px-4 py-3 md:py-4">

          {/* LOGO */}
          <NavLink to="/" className="flex items-center gap-2 shrink-0">
            <img src={logoDark} alt="Logo" className="h-16 w-auto object-contain dark:hidden" />
            <img src={logoLight} alt="Logo" className="h-16 w-auto object-contain hidden dark:block" />
          </NavLink>

          {/* DESKTOP LINKS */}
          <ul className="hidden md:flex items-center gap-6 lg:gap-8">
            {navLinks?.map((link) => {
              const isEnd = link.path === '/';
              return (
              <li key={link.path}>
                <NavLink to={link.path} className={activeLinks} end={isEnd}>
                  {link.name}
                </NavLink>
              </li>
              );
            })}
          </ul>

          {/* RIGHT ACTIONS */}
          <div className="hidden md:flex items-center gap-4">
            <button 
              onClick={toggleTheme} 
              className={`p-2 rounded-full transition-colors cursor-pointer ${isHome && !scrolled ? 'text-white hover:bg-white/10' : 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
              aria-label="Toggle theme"
            >
              {theme === 'dark' ? <FiSun size={20} /> : <FiMoon size={20} />}
            </button>
            <DesktopAuthButtons />
          </div>

          {/* MOBILE BUTTONS */}
          <div className="md:hidden flex items-center gap-3">
            <button 
              onClick={toggleTheme} 
              className={isHome && !scrolled && !menuOpen ? 'text-primary' : 'text-primary'}
              aria-label="Toggle theme"
            >
              {theme === 'dark' ? <FiSun size={24} /> : <FiMoon size={24} />}
            </button>
            <button
              onClick={() => setMenuOpen(true)}
              className={isHome && !scrolled && !menuOpen ? 'text-primary' : 'text-primary'}
            >
              <FiMenu size={28} />
            </button>
          </div>
        </nav>
      </header>

      {/* MOBILE OVERLAY */}
      {menuOpen && (
        <div
          onClick={() => setMenuOpen(false)}
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-60 md:hidden transition-opacity"
        />
      )}

      {/* MOBILE DRAWER */}
      <div
        className={`
          fixed top-0 right-0 h-full w-4/5 max-w-sm bg-surface
          z-70 shadow-2xl transform transition-transform duration-300 ease-in-out
          md:hidden flex flex-col
          ${menuOpen ? "translate-x-0" : "translate-x-full"}
        `}
      >
        <div className="flex items-center justify-between p-5 border-b border-slate-100 dark:border-slate-800/50">
          <NavLink to="/" onClick={() => setMenuOpen(false)} className="flex items-center gap-2 shrink-0">
            <img src={logoDark} alt="Logo" className="h-8 w-auto object-contain dark:hidden" />
            <img src={logoLight} alt="Logo" className="h-8 w-auto object-contain hidden dark:block" />
          </NavLink>
          <button
            onClick={() => setMenuOpen(false)}
            className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500 dark:text-slate-400"
          >
            <FiX size={20} />
          </button>
        </div>

        <div className="p-5 flex-1 overflow-y-auto flex flex-col gap-2">
          {navLinks?.map((link) => {
            const isEnd = link.path === '/';
            return (
            <NavLink
              key={link.path}
              to={link.path}
              end={isEnd}
              className={({ isActive }) =>
                `px-4 py-3 rounded-lg text-lg font-medium transition-colors ${isActive
                  ? "bg-[#E85D04]/10 text-[#E85D04] dark:bg-[#E85D04]/20"
                  : "text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800"
                }`
              }
              onClick={() => setMenuOpen(false)}
            >
              {link.name}
            </NavLink>
            );
          })}

          <div className="mt-auto">
            <MobileAuthButtons />
          </div>
        </div>
      </div>
    </>
  );
});

export default Navbar;

import { Outlet, useLocation, Link } from "react-router-dom";
import { useState, useEffect, Suspense, memo } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { FiSun, FiMoon, FiChevronRight, FiChevronLeft, FiMenu, FiBell } from "react-icons/fi";

import Sidebar from "./Sidebar";
import NotificationBell from "./NotificationBell";
import { sidebarConfig } from "./sidebar.config";
import { useAuth } from "../../context/AuthContext";
import GlobalLoader from "../../components/ui/GlobalLoader";

const pageVariants = {
  initial: { opacity: 0 },
  animate: { opacity: 1, transition: { duration: 0.5, ease: "easeOut" } },
  exit:    { opacity: 0, transition: { duration: 0.2, ease: "easeIn" } }
};

const DashboardLayout = memo(({ theme, toggleTheme }) => {
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const { user } = useAuth();
  const location = useLocation();

  const roleConfig = sidebarConfig[user?.role] || {};
  const fallbackTitle = roleConfig.title || "Admin Panel";

  useEffect(() => {
    if (theme === "dark") {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  }, [theme]);

  const pathSegments = location.pathname.split("/").filter(Boolean);

  const getBreadcrumbLabel = (segment) => {
    return segment
      .replace(/-/g, " ")
      .replace(/\b\w/g, (c) => c.toUpperCase());
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-300 bg-background text-primary`}>
      
      {/* Sidebar Navigation */}
      <Sidebar
        collapsed={collapsed}
        setCollapsed={setCollapsed}
        mobileOpen={mobileOpen}
        setMobileOpen={setMobileOpen}
      />

      {/* main Layout Container */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        
        {/* TOP NAVBAR */}
        <header className="h-16 flex items-center justify-between px-6 bg-white/70 dark:bg-[#050816]/70 backdrop-blur-md border-b border-slate-200/80 dark:border-slate-800/40 sticky top-0 z-30">
          
          {/* LEFT - Collapsible Trigger & Breadcrumbs */}
          <div className="flex items-center gap-4">
            
            {/* Desktop Collapse Toggle */}
            <button
              onClick={() => setCollapsed(!collapsed)}
              title={collapsed ? "Expand sidebar" : "Collapse sidebar"}
              className="hidden md:flex items-center justify-center w-9 h-9 rounded-xl border border-slate-200 dark:border-slate-850 hover:bg-slate-100 dark:hover:bg-slate-900 text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white transition duration-200 cursor-pointer"
            >
              {collapsed ? <FiChevronRight size={16} /> : <FiChevronLeft size={16} />}
            </button>

            {/* Mobile Sidebar Toggle */}
            <button
              onClick={() => setMobileOpen(true)}
              className="md:hidden flex items-center justify-center w-9 h-9 rounded-xl border border-slate-200 dark:border-slate-850 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-900 cursor-pointer"
            >
              <FiMenu size={18} />
            </button>

            {/* Dynamic Breadcrumbs */}
            <nav className="flex items-center gap-1.5 text-sm font-semibold text-slate-500 dark:text-slate-400">
              <span className="text-slate-400 dark:text-slate-600">TravelBharat</span>
              {pathSegments.map((segment, idx) => {
                const url = `/${pathSegments.slice(0, idx + 1).join("/")}`;
                const isLast = idx === pathSegments.length - 1;
                
                return (
                  <div key={url} className="flex items-center gap-1.5">
                    <FiChevronRight size={14} className="text-slate-300 dark:text-slate-700" />
                    {isLast ? (
                      <span className="text-[#E85D04] dark:text-[#FFA034] truncate max-w-[120px] sm:max-w-[200px]">
                        {getBreadcrumbLabel(segment)}
                      </span>
                    ) : (
                      <Link 
                        to={url} 
                        className="hover:text-slate-800 dark:hover:text-white transition"
                      >
                        {getBreadcrumbLabel(segment)}
                      </Link>
                    )}
                  </div>
                );
              })}
            </nav>
          </div>

          {/* RIGHT - Actions, Theme Switcher & Admin Info */}
          <div className="flex items-center gap-3">
            
            {/* Quick Notification Bell */}
            <NotificationBell />

            {/* Dark / Light Theme Toggle */}
            <button
              onClick={toggleTheme}
              className="w-9 h-9 flex items-center justify-center rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 transition"
              title={theme === "light" ? "Switch to dark mode" : "Switch to light mode"}
            >
              {theme === "light" ? <FiMoon size={18} /> : <FiSun size={18} />}
            </button>

            {/* Separator */}
            <div className="w-px h-6 bg-slate-200 dark:bg-slate-800" />

            {/* User display badge */}
            <div className="hidden sm:flex flex-col text-right">
              <span className="text-sm font-bold text-slate-800 dark:text-slate-200">
                {user?.name || "Administrator"}
              </span>
              <span className="text-[10px] uppercase tracking-wider font-extrabold text-[#E85D04] dark:text-[#FFA034]">
                {user?.role || "Admin"}
              </span>
            </div>

          </div>
        </header>

        {/* CONTENT AREA */}
        <main className="flex-1 overflow-y-auto p-6 md:p-8 max-w-[1920px] mx-auto w-full relative z-10">
          
          {/* Subtle page background details */}
          <div className="absolute top-0 right-10 w-96 h-96 bg-[#E85D04]/2 blur-[100px] rounded-full pointer-events-none -z-10" />
          
          <AnimatePresence mode="popLayout">
            <motion.div
              key={location.pathname}
              variants={pageVariants}
              initial="initial"
              animate="animate"
              exit="exit"
            >
              <Suspense fallback={<GlobalLoader />}>
                <Outlet />
              </Suspense>
            </motion.div>
          </AnimatePresence>
        </main>
      </div>
    </div>
  );
});

export default DashboardLayout;

import { NavLink, Link, useNavigate, useLocation } from "react-router-dom";
import { FiX, FiSettings, FiLogOut, FiUser, FiChevronRight, FiChevronLeft } from "react-icons/fi";
import { useQuery } from "@tanstack/react-query";
import http from "../../lib/axios";
import { useState, useRef } from "react";
import { createPortal } from "react-dom";
import { sidebarConfig } from "./sidebar.config";
import { useAuth } from "../../context/AuthContext";
import logoDark from "../../assets/logo_dark.png";
import logoLight from "../../assets/logo_light.png";
import { toast } from "react-toastify";

// Portal tooltip for collapsed state
const SidebarTooltip = ({ label, y }) =>
  createPortal(
    <div
      className="fixed left-20 z-[9999] flex items-center pointer-events-none animate-fadeIn"
      style={{ top: `${y}px`, transform: "translateY(-50%)" }}
    >
      <div className="w-0 h-0 border-t-6 border-t-transparent border-b-6 border-b-transparent border-r-6 border-r-slate-800 dark:border-r-slate-900" />
      <div className="bg-slate-800 dark:bg-slate-900 text-white text-xs font-semibold px-3 py-1.5 rounded-lg shadow-xl whitespace-nowrap">
        {label}
      </div>
    </div>,
    document.body
  );

const Sidebar = ({ collapsed, setCollapsed, mobileOpen, setMobileOpen }) => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [loggingOut, setLoggingOut] = useState(false);
  const [tooltip, setTooltip] = useState({ show: false, label: "", y: 0 });

  const { data: notificationsData } = useQuery({
    queryKey: ["adminNotifications"],
    queryFn: async () => {
      const res = await http.get("/notifications/admin");
      return res.data;
    },
    enabled: user?.role === "admin"
  });
  const unreadCount = notificationsData?.unreadCount || 0;

  const roleConfig = sidebarConfig[user?.role] || {};
  const navLinks = roleConfig.links || [];

  const handleMouseEnter = (e, label) => {
    if (!collapsed) return;
    const rect = e.currentTarget.getBoundingClientRect();
    setTooltip({ show: true, label, y: rect.top + rect.height / 2 });
  };

  const handleMouseLeave = () => {
    setTooltip({ show: false, label: "", y: 0 });
  };

  const handleLogout = async () => {
    if (loggingOut) return;
    try {
      setLoggingOut(true);
      await logout();
      toast.success("Logged out successfully!");
      navigate("/auth");
    } catch (error) {
      console.error(error);
      toast.error("Logout failed!");
    } finally {
      setLoggingOut(false);
    }
  };

  return (
    <>
      {collapsed && tooltip.show && (
        <SidebarTooltip label={tooltip.label} y={tooltip.y} />
      )}

      {/* Mobile overlay */}
      {mobileOpen && (
        <div
          onClick={() => setMobileOpen(false)}
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-xs z-40 md:hidden"
        />
      )}

      <aside
        className={`fixed md:sticky top-0 left-0 z-50 h-screen min-h-screen overflow-y-auto flex flex-col bg-white dark:bg-[#050816] border-r border-slate-200/80 dark:border-slate-800/60 shadow-xl transition-all duration-300 ease-in-out ${mobileOpen ? "translate-x-0" : "-translate-x-full md:translate-x-0"
          } ${collapsed ? "md:w-20 w-72" : "md:w-64 w-72"}`}
      >
        {/* HEADER / LOGO */}
        <div className="h-16 flex items-center justify-between px-4 border-b border-slate-100 dark:border-slate-800/40">
          <Link to="/" className="flex items-center gap-3">
            <img
              src={logoDark}
              alt="TravelBharat Logo"
              className="h-8 w-auto object-contain shrink-0 dark:hidden"
            />
            <img
              src={logoLight}
              alt="TravelBharat Logo"
              className="h-8 w-auto object-contain shrink-0 hidden dark:block"
            />
            {!collapsed && (
              <span className="font-black text-slate-800 dark:text-white tracking-wide text-base bg-linear-to-r from-[#E85D04] to-[#FF9E00] bg-clip-text text-transparent">
                TravelBharat
              </span>
            )}
          </Link>

          <button
            className="md:hidden text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white cursor-pointer"
            onClick={() => setMobileOpen(false)}
          >
            <FiX size={20} />
          </button>
        </div>

        {/* NAVIGATION LINKS */}
        <nav className="flex-1 px-3 py-4 space-y-1 overflow-y-auto scrollbar-none">
          {navLinks.map(({ to, label, icon: Icon }) => {
            const isActive = to === '/'
              ? location.pathname === '/'
              : to === '/admin' || to === '/user'
                ? location.pathname === to
                : location.pathname.startsWith(to);
            return (
              <div
                key={to}
                onMouseEnter={(e) => handleMouseEnter(e, label)}
                onMouseLeave={handleMouseLeave}
              >
                <Link
                  to={to}
                  onClick={() => setMobileOpen(false)}
                  className={`relative flex items-center rounded-xl transition duration-200 group
                    ${collapsed ? "justify-center px-0" : "gap-3.5 px-4"}
                    py-3 text-sm font-semibold
                    ${isActive
                      ? "bg-[#E85D04]/10 text-[#E85D04] dark:text-[#FFA034] shadow-xs"
                      : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-900 hover:text-slate-900 dark:hover:text-white"
                    }`}
                >
                  {isActive && (
                    <span className="absolute left-0 top-3 bottom-3 w-1 bg-[#E85D04] rounded-r-full" />
                  )}
                  <Icon
                    size={20}
                    className={`shrink-0 transition-transform group-hover:scale-105 ${isActive ? "text-[#E85D04]" : "text-slate-400 dark:text-slate-500 group-hover:text-slate-600 dark:group-hover:text-slate-350"
                      }`}
                  />
                  {!collapsed && <span className="flex-1">{label}</span>}
                  {!collapsed && to === "/admin/notifications" && unreadCount > 0 && (
                    <span className="bg-[#E85D04] text-white text-[10px] font-bold px-2 py-0.5 rounded-full">
                      {unreadCount > 99 ? '99+' : unreadCount}
                    </span>
                  )}
                  {collapsed && to === "/admin/notifications" && unreadCount > 0 && (
                    <span className="absolute top-2 right-2 w-2 h-2 bg-[#E85D04] rounded-full" />
                  )}
                </Link>
              </div>
            );
          })}
        </nav>

        {/* PROFILE FOOTER SECTION */}
        <div className="p-3 border-t border-slate-100 dark:border-slate-800/40 bg-slate-50/50 dark:bg-[#070D1F]/30">
          {collapsed ? (
            <div className="flex flex-col items-center gap-3 py-1">
              <Link to={user?.role === 'admin' ? "/admin/profile" : "/user/profile"}>
                {user?.profileImage ? (
                  <img
                    src={user.profileImage}
                    alt={user.name}
                    className="w-10 h-10 rounded-full object-cover border-2 border-[#E85D04]/30 hover:border-[#E85D04] transition duration-200"
                  />
                ) : (
                  <div className="w-10 h-10 rounded-full bg-[#E85D04]/10 text-[#E85D04] flex items-center justify-center font-bold border border-[#E85D04]/20 hover:border-[#E85D04] transition duration-200">
                    {user?.name ? user.name[0].toUpperCase() : <FiUser />}
                  </div>
                )}
              </Link>

              <button
                onClick={handleLogout}
                disabled={loggingOut}
                title="Logout"
                className="p-2 rounded-xl text-slate-400 hover:text-red-500 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-500/10 transition cursor-pointer"
              >
                <FiLogOut size={18} />
              </button>
            </div>
          ) : (
            <div className="space-y-3">
              <div className="flex items-center gap-3">
                <Link to={user?.role === 'admin' ? "/admin/profile" : "/user/profile"} className="shrink-0">
                  {user?.profileImage ? (
                    <img
                      src={user.profileImage}
                      alt={user.name}
                      className="w-10 h-10 rounded-full object-cover border-2 border-slate-200 dark:border-slate-800"
                    />
                  ) : (
                    <div className="w-10 h-10 rounded-full bg-[#E85D04]/10 text-[#E85D04] flex items-center justify-center font-bold border border-[#E85D04]/20">
                      {user?.name ? user.name[0].toUpperCase() : <FiUser />}
                    </div>
                  )}
                </Link>

                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-slate-800 dark:text-white truncate">
                    {user?.name || "Admin user"}
                  </p>
                  <p className="text-xs text-slate-400 dark:text-slate-500 truncate">
                    {user?.email || "admin@travelbharat.com"}
                  </p>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex items-center justify-between gap-2 pt-1 border-t border-slate-100 dark:border-slate-800/40">
                <Link
                  to={user?.role === 'admin' ? "/admin/profile" : "/user/profile"}
                  className="flex items-center gap-1.5 px-2.5 py-1.5 text-xs font-semibold text-slate-600 hover:text-[#E85D04] dark:text-slate-400 dark:hover:text-white rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition"
                >
                  <FiSettings size={14} />
                  <span>Profile</span>
                </Link>

                <button
                  onClick={handleLogout}
                  disabled={loggingOut}
                  className="flex items-center gap-1.5 px-2.5 py-1.5 text-xs font-semibold text-red-500 hover:text-red-600 dark:text-red-400 dark:hover:text-red-300 rounded-lg hover:bg-red-50 dark:hover:bg-red-500/10 transition cursor-pointer"
                >
                  <FiLogOut size={14} />
                  <span>{loggingOut ? "..." : "Logout"}</span>
                </button>
              </div>
            </div>
          )}
        </div>
      </aside>
    </>
  );
};

export default Sidebar;

import { Outlet, useLocation } from "react-router-dom";
import { AnimatePresence, motion } from "framer-motion";
import { Suspense, useEffect, memo } from "react";
import Footer from "../core/Footer";
import Navbar from "../core/Navbar";
import GlobalLoader from "../../components/ui/GlobalLoader";

const pageVariants = {
  initial: { opacity: 0 },
  animate: { opacity: 1, transition: { duration: 0.5, ease: "easeOut" } },
  exit:    { opacity: 0, transition: { duration: 0.2, ease: "easeIn" } }
};

const PublicLayout = memo(() => {
  const location = useLocation();

  return (
    <div className="flex flex-col min-h-screen bg-background text-primary transition-colors duration-300">
      <Navbar />
      <main className="flex-1">
        <AnimatePresence mode="popLayout">
          <motion.div
            key={location.pathname}
            variants={pageVariants}
            initial="initial"
            animate="animate"
            exit="exit"
          >
            <Suspense fallback={<GlobalLoader />}>
              <Outlet />
            </Suspense>
          </motion.div>
        </AnimatePresence>
      </main>
      <Footer />
    </div>
  );
});

export default PublicLayout;
